typedef unsigned int size_t;
#define NULL 0
#define assert(exp) ((void)0)
#define NEW new(0,__PRETTY_FUNCTION__,0)
void *operator new(size_t size, unsigned int flags, const char *descript, int line);

class po { char data[64]; };
class bone;
class bone_interface
{
  protected:
    bone *my_bone;
};
class link_interface : public bone_interface
{
  protected:
    bone * my_parent;
    bone * my_child;
    bone * my_brother;
    bool link_manages_abs_po;
    friend class bone;
  public:
    void set_handed_axis_family(int axis);
};
class bone
{
  char signaller_data[12];
  protected:
    po my_rel_po;
    po *my_abs_po;
    po *my_handed_abs_po;
    int bone_id;
    void *my_sector;
    int flip_axis;
    bool is_part_of_skeleton;
    link_interface * my_link_interface;
  public:
    bool has_link_ifc() const { return (my_link_interface != NULL); }
    link_interface * link_ifc() const
    {
      assert(my_link_interface);
      return my_link_interface;
    }
    void set_handed_axis(int axis)
    {
        flip_axis = axis;
        if (!is_part_of_skeleton && !my_handed_abs_po)
        {
            assert(my_handed_abs_po == NULL);
            my_handed_abs_po = NEW po;
        }

        if (has_link_ifc())
            link_ifc()->set_handed_axis_family(axis);
    }
};

void link_interface::set_handed_axis_family(int axis)
{
\tassert(my_bone);

  // update my children
  if (my_child != NULL)
  {
    assert (my_child->has_link_ifc());
    my_child->set_handed_axis(axis);

    // update my brothers (part of update children)
    bone *it = my_child;
    assert(it->has_link_ifc());
    while(it->link_ifc()->my_brother != NULL)
    {
      it->link_ifc()->my_brother->set_handed_axis(axis);
      it = it->link_ifc()->my_brother;
      assert(!it || it->has_link_ifc());
    }
  }
}
